import pandas as pd

def clean(df):
    df["body_mass_g"] = df["body_mass_g"].str.replace(',', '').astype(float)
    mask = (df["body_mass_g"] >= 2500) & (df["body_mass_g"] <= 6500) & (df["sex"].isin(["male", "female"]))
    return df[mask]

def answer(df):
    grouped = df.groupby("sex")["body_mass_g"].mean().to_dict()
    return {k: v for k, v in grouped.items() if pd.notna(v)}
